 void bindEvent(View v,Events.Group g){TextView scheduleState=v.findViewWithTag("schedule-state");if(scheduleState!=null){String label=scheduleLabel(g);scheduleState.setText(label);scheduleState.setVisibility(label.isEmpty()?View.GONE:View.VISIBLE);}if(view.equals("live")){TextView caption=v.findViewWithTag("signal-caption");if(caption!=null){String text=LiveState.phase(g,System.currentTimeMillis())==LiveState.Phase.SOON?"开赛后自动更新":signalCaption(g);if(!android.text.TextUtils.equals(caption.getText(),text))caption.setText(text);}}v.setTag(g.id);v.setFocusable(true);v.setClickable(true);v.setOnClickListener(node->open(g));v.setOnLongClickListener(node->{try{boolean added=Library.toggle(this,g);showHint(added?"已收藏赛事":"已取消收藏");render();}catch(Exception e){Ui.message(this,"收藏失败",e.getMessage());}return true;});v.setOnFocusChangeListener((node,yes)->Ui.focusSurface(node,yes));}
