 void sortOptions(){Ui.options(this,"赛程排列",new String[]{(scheduleMode.equals("time")?"✓ ":"")+"按日期与开赛时间",(scheduleMode.equals("league")?"✓ ":"")+"按日期与联赛 / 杯赛",(scheduleAll?"✓ ":"")+"显示已结束赛事"},i->{if(i==2)scheduleAll=!scheduleAll;else scheduleMode=i==0?"time":"league";syncControls();render();scrollTop();});}
 void pickLeague(){TreeMap<String,Integer> names=new TreeMap<String,Integer>();for(Events.Group g:Events.group(matches.values())){if(!include(g,false))continue;String key=EventOrder.league(g);names.put(key,names.containsKey(key)?names.get(key)+1:1);}ArrayList<String> values=new ArrayList<String>();values.add("全部联赛");values.addAll(names.keySet());String[] labels=new String[values.size()];for(int i=0;i<labels.length;i++){String value=values.get(i);labels[i]=(league.equals(value)?"✓ ":"")+value+(i==0?"":"  ·  "+names.get(value)+" 场");}Ui.options(this,"选择联赛 / 杯赛",labels,i->{league=values.get(i);visibleLimit=Ui.cardLimit();syncControls();render();scrollTop();});}
 void applySearch(String text){String next=text.trim();if(next.isEmpty()){clearSearch();return;}View focused=getCurrentFocus();searchSession.begin(next,new SearchSession.Snapshot(source,category,league,date,contentScroll.getScrollY(),focused!=null&&focused.getTag() instanceof String?(String)focused.getTag():"action:search"));query=next;visibleLimit=Ui.cardLimit();exitArmed=0;syncControls();render();scrollTop();searchExit.requestFocus();}
