 boolean hasFilters(){return !source.equals("全部来源")||!category.equals("全部")||!league.equals("全部联赛")||!date.isEmpty()&&!(view.equals("schedule")&&date.equals(EventOrder.dayKey(System.currentTimeMillis())));}
 void resetFilters(){source="全部来源";category="全部";league="全部联赛";date=view.equals("schedule")?EventOrder.dayKey(System.currentTimeMillis()):"";syncControls();renderConnections();render();scrollTop();}
 @Override public void onBackPressed(){SearchSession.Back action=SearchSession.back(query,hasFilters(),view,exitArmed>0&&SystemClock.elapsedRealtime()-exitArmed<2200);switch(action){case SEARCH:clearSearch();showHint("已退出搜索，恢复原来的浏览结果");break;case FILTERS:resetFilters();showHint("已清除筛选");break;case HOME:switchView("live");menus.get("live").requestFocus();break;case ARM_EXIT:exitArmed=SystemClock.elapsedRealtime();showHint("再按一次返回退出球场 TV");break;case EXIT:super.onBackPressed();break;}}
    void search(){LinearLayout content=Ui.column(this);EditText edit=new EditText(this);edit.setSingleLine();edit.setInputType(android.text.InputType.TYPE_CLASS_TEXT);edit.setFocusable(true);edit.setFocusableInTouchMode(true);edit.setTextColor(Ui.TEXT);edit.setHintTextColor(Ui.MUTED);edit.setHint("球队 / 联赛 / 来源");edit.setPadding(dp(14),dp(12),dp(14),dp(12));edit.setBackground(Ui.shape(Ui.BG,Ui.BORDER));edit.setText(query);edit.setImeOptions(EditorInfo.IME_ACTION_SEARCH);content.addView(edit,new LinearLayout.LayoutParams(-1,dp(56)));Dialog dialog=Ui.dialog(this,"搜索赛事",content);dialog.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);edit.requestFocus();edit.setSelection(edit.length());edit.postDelayed(()->{if(dialog.isShowing())((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(edit,InputMethodManager.SHOW_IMPLICIT);},200);LinearLayout actions=new LinearLayout(this);content.addView(actions);actions.addView(Ui.button(this,"搜索",v->{dialog.dismiss();applySearch(edit.getText().toString());}));actions.addView(Ui.button(this,"清空",v->{dialog.dismiss();clearSearch();}));TextView help=Ui.text(this,"遥控器可直接选择球队；文字框支持系统输入法与外接键盘",12,Ui.MUTED);content.addView(help);HorizontalScrollView quickScroll=new HorizontalScrollView(this);LinearLayout quick=new LinearLayout(this);quickScroll.addView(quick);content.addView(quickScroll);LinkedHashSet<String> teams=new LinkedHashSet<String>();for(Feeds.Match item:matches.values()){if(teams.size()>=6)break;if(!item.league.isEmpty()&&!SourceSafety.promotional(item.league))teams.add(item.league);}for(Feeds.Match m:matches.values()){if(!m.home.isEmpty())teams.add(m.home);if(!m.away.isEmpty())teams.add(m.away);}int teamCount=0;for(String team:teams){if(teamCount++>=24)break;Button choice=Ui.button(this,Events.shortName(team),v->{edit.setText(team);edit.setSelection(edit.length());});choice.setTextSize(13);quick.addView(choice);} LinearLayout keyboard=Ui.column(this);keyboard.setVisibility(View.GONE);actions.addView(Ui.button(this,"电视键盘",v->{keyboard.setVisibility(keyboard.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE);((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(edit.getWindowToken(),0);}));content.addView(keyboard);String alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";LinearLayout keys=null;for(int k=0;k<alphabet.length();k++){if(k%9==0){keys=new LinearLayout(this);keyboard.addView(keys);}final String letter=alphabet.substring(k,k+1);Button key=Ui.button(this,letter,v->{int cursor=Math.max(0,edit.getSelectionStart());edit.getText().insert(cursor,letter);});key.setTextSize(13);key.setMinWidth(0);key.setMinimumWidth(0);keys.addView(key,new LinearLayout.LayoutParams(0,dp(38),1));}LinearLayout editing=new LinearLayout(this);keyboard.addView(editing);editing.addView(Ui.button(this,"空格",v->{int cursor=Math.max(0,edit.getSelectionStart());edit.getText().insert(cursor," ");}));editing.addView(Ui.button(this,"退格",v->{int cursor=Math.max(0,edit.getSelectionStart());if(cursor>0){int previous=Character.offsetByCodePoints(edit.getText(),cursor,-1);edit.getText().delete(previous,cursor);}})); edit.setOnEditorActionListener((v,id,event)->{if(id==EditorInfo.IME_ACTION_SEARCH){dialog.dismiss();applySearch(edit.getText().toString());return true;}return false;});}
    void open(Events.Group group){try{Library.remember(this,group);Intent intent=new Intent(this,PlayerActivity.class);intent.putExtra("members",Library.records(group).toString());intent.putExtra("eventId",group.id);intent.putExtra("waiting",group.lead().kind.equals("live")&&(LiveState.phase(group,System.currentTimeMillis())==LiveState.Phase.SOON||group.start>System.currentTimeMillis()));intent.putExtra("sourceExplicit",!source.equals("全部来源"));intent.putExtra("preferred",source.equals("全部来源")?getSharedPreferences("player",0).getString("preferred",""):source);startActivityForResult(intent,10);}catch(Exception e){Ui.message(this,"暂时无法打开",e.getMessage());}}
    protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&result==RESULT_FIRST_USER)switchView("live");}
    void connectionDetails(String name){if(!SourcePreferences.enabled(this,name)){LinearLayout removed=Ui.column(this);removed.addView(Ui.text(this,"此来源已移除，不再获取赛事或参与自动换源。收藏和观看记录仍保留。",16,Ui.TEXT));Dialog restore=Ui.dialog(this,SourceCatalog.label(name)+" · 已移除",removed);removed.addView(Ui.button(this,"重新加入此来源",v->{restore.dismiss();changeSource(name,true);}));return;}LinearLayout body=Ui.column(this);TextView text=Ui.text(this,errors.containsKey(name)?errors.get(name):status.containsKey(name)?status.get(name):"尚未连接",16,Ui.TEXT);text.setPadding(0,0,0,dp(16));body.addView(text);body.addView(Ui.text(this,"设备时间："+EventOrder.format("yyyy-MM-dd HH:mm",System.currentTimeMillis())+"（北京时间）\n"+NetCompat.engine,13,Ui.MUTED));Dialog dialog=Ui.dialog(this,SourceCatalog.label(name)+" · 连接诊断",body);body.addView(Ui.button(this,"仅看此来源",v->{dialog.dismiss();source=name;visibleLimit=Ui.cardLimit();renderConnections();render();scrollTop();}));body.addView(Ui.button(this,"移除此来源（可重新加入）",v->{dialog.dismiss();changeSource(name,false);}));body.addView(Ui.button(this,"重新连接",v->{dialog.dismiss();fetch(name,1,"");}));}
    String signalCaption(Events.Group g){return "已核验 "+StreamHealth.verified(g,System.currentTimeMillis())+" 个信号";}
    String scheduleLabel(Events.Group g){long now=System.currentTimeMillis();Feeds.Match m=g.lead();if(LiveState.finished(g,now))return "已结束";if(m.eventState.equals("finished")||m.status.equals("finished"))return "已结束";if(m.status.equals("cancelled"))return "已取消";if(g.start>now||LiveState.phase(g,now)==LiveState.Phase.SOON)return "未开赛";return LiveState.phase(g,now)!=LiveState.Phase.HIDE&&liveChecks.ensure(g)?"直播中":"";}
    void mergeRecent(String name){for(Feeds.Match m:LiveCatalog.recent(System.currentTimeMillis()))if(m.source.equals(name)&&SourcePreferences.enabled(this,name)){Feeds.Match existing=matches.get(m.key());if(existing==null||!LiveState.hasRoom(existing)&&LiveState.hasRoom(m))matches.put(m.key(),m);}}
    void supplement(final String name,final int token){requests.execute(()->{String cursor="";for(int page=1;page<=1&&!dead&&token==generation;page++){try{Feeds.Page extra=Feeds.fetch(name,"schedule",page,cursor);final ArrayList<Feeds.Match> rows=extra.items;runOnUiThread(()->{if(dead||token!=generation||!view.equals("live")||!SourcePreferences.enabled(this,name))return;LiveCatalog.remember(rows,System.currentTimeMillis());mergeRecent(name);dataRevision++;renderSoon();});if(!extra.more||extra.items.isEmpty())break;cursor=extra.cursor;}catch(Exception error){android.util.Log.i("BallTVCatalog",name+" schedule supplement unavailable: "+error.getClass().getSimpleName());break;}}});}
    void verificationDetails(){Ui.message(this,"赛事与核验进度","本次目录："+catalogRows+" 条来源记录，合并为 "+catalogEvents+" 场赛事。\n已过滤结束、过期或资料不足："+filteredEvents+" 场（按合并赛事统计）。\n当前筛选显示："+visibleGroups.size()+" 场，首页仅展示取得有效视频信号的直播及稍后开赛房间。\n\n"+liveChecks.report());}
    void networkDiagnostics(){StringBuilder text=new StringBuilder("Android "+Build.VERSION.RELEASE+" / API "+Build.VERSION.SDK_INT+"\n设备："+Build.MANUFACTURER+" "+Build.MODEL+"\n"+NetCompat.engine+(NetCompat.detail.isEmpty()?"":"\n"+NetCompat.detail)+"\n北京时间："+EventOrder.format("yyyy-MM-dd HH:mm",System.currentTimeMillis())+"\n\n");for(String name:SourceCatalog.ALL)text.append(SourceCatalog.label(name)).append("：").append(errors.containsKey(name)?errors.get(name):loading.contains(name)?"连接中":status.containsKey(name)?status.get(name):"尚未检查").append("\n");text.append("\n").append(liveChecks.report()).append("\n应用 HTTP 代理：");try{text.append(java.net.ProxySelector.getDefault().select(new java.net.URI(Feeds.COFFEE)).toString());}catch(Exception ignored){text.append("未知");}text.append("（系统 VPN/TUN 路由另行生效）\n\n可用入口：\n");for(String name:SourceCatalog.ALL){String selected=SiteMirrors.current(name);if(!selected.isEmpty())text.append(SourceCatalog.label(name)).append("：").append(selected).append("\n");}text.append("\n失败来源按确定查看原因；来源管理可单独重试。电视与电脑网络不同、代理、DNS、系统时间或站点限制都可能影响连接。");Ui.message(this,"来源连接诊断",text.toString());}
    void changeSource(String name,boolean enabled){SourcePreferences.setEnabled(this,name,enabled);if(!enabled&&source.equals(name))source="全部来源";loading.remove(name);errors.remove(name);more.remove(name);pages.remove(name);status.put(name,enabled?"等待":"已移除");dataRevision++;if(view.equals("favorites")||view.equals("history")){reload();}else{if(!enabled){Iterator<Feeds.Match> it=matches.values().iterator();while(it.hasNext())if(it.next().source.equals(name))it.remove();}else fetch(name,1,"");renderConnections();render();}showHint(enabled?"已重新加入 "+SourceCatalog.label(name):"已移除，可在来源管理中重新加入");providers.get("全部来源").requestFocus();}
    void sourceManager() {
        ArrayList<String> names = new ArrayList<>();
        ArrayList<String> rows = new ArrayList<>();
        for (String name : SourceCatalog.ALL) {
            if (!SourceCatalog.inCategory(name, category)) continue;
            names.add(name);
            String connection = !SourcePreferences.enabled(this, name) ? "已移除"
                : loading.contains(name) ? "连接中" : errors.containsKey(name) ? "连接失败"
                : status.containsKey(name) ? status.get(name) : "尚未连接";
            rows.add(SourceCatalog.label(name) + " · " + connection);
        }
        Ui.options(this, "来源管理 · 重连、仅看或移除", rows.toArray(new String[0]),
            i -> connectionDetails(names.get(i)));
    }
    void performance(){String mode=getSharedPreferences("performance",0).getString("mode","auto");Ui.options(this,"性能与封面 · 当前"+(Ui.LEAN?"流畅模式":"完整模式"),new String[]{(mode.equals("auto")?"✓ ":"")+"自动 · 旧电视优先流畅",(mode.equals("lean")?"✓ ":"")+"流畅 · 减少特效与后台抓图",(mode.equals("full")?"✓ ":"")+"完整 · 更多卡片与封面尝试"},i->{getSharedPreferences("performance",0).edit().putString("mode",new String[]{"auto","lean","full"}[i]).apply();recreate();});}
    boolean quietForImages(){return foreground&&windowActive&&SystemClock.elapsedRealtime()-lastInput>1400&&SystemClock.elapsedRealtime()-lastCatalog>5000;}
    void appearance(){String mode=getSharedPreferences("appearance",0).getString("mode","auto");Ui.options(this,"外观与主题",new String[]{(mode.equals("light")?"✓ ":"")+"浅色",(mode.equals("dark")?"✓ ":"")+"深色",(mode.equals("auto")?"✓ ":"")+"随时间自动 · 07:00–19:00 浅色"},i->{getSharedPreferences("appearance",0).edit().putString("mode",new String[]{"light","dark","auto"}[i]).apply();recreate();});}
    void settings(){Ui.options(this,"球场 TV · 0.15.9 · 标准版",new String[]{"来源与功能","遥控器操作","兼容性与隐私","外观与主题","来源连接诊断","性能与封面","画质与增强","关于与交流","检查更新","赞赏支持"},w->{if(w==7){ProjectInfo.about(this);return;}if(w==8){ReleaseUpdates.show(this);return;}if(w==9){ProjectInfo.donation(this);return;}if(w==6){VideoSettings.show(this,null);return;}if(w==5){performance();return;}if(w==4){networkDiagnostics();return;}if(w==3){appearance();return;}Ui.message(this,w==0?"赛事来源":w==1?"遥控器操作":"Android 5.0+",w==0?"大米、咖啡、豆包、178、88看球、JRKAN、雨燕/7Live、74体育/球吧、看球通、So米、龙门、鲸鱼、天天看球、海星体育，以及玩球/看球/飞速/飞球/比赛直播联合接入（共用房间去重）。\n\n相同队伍、项目且开赛时间接近的比赛合并展示；无法可靠匹配的保持独立。部分来源暂未接入回放。失败来源可在来源管理中独立重试；直播目录每 3 分钟刷新，并核验赛事状态与视频信号。\n\n雨燕、87直播与 7Live 共用房间接口，来源栏合并显示为雨燕/87，不重复计数。龙门、鲸鱼、天天看球、海星体育和联合站组目前只提供直播目录。":w==1?"首页点击来源直接筛选，失败来源按确定可查看原因。来源管理可单独重试。方向键选择，确定观看；菜单键打开当前项目操作，可收藏赛事。播放器菜单键打开来源与线路侧栏。确定键显示控制，回放左右键快进/后退。返回先关闭侧栏或控制，再退出。\n\n搜索结果可点“退出搜索”或按返回键恢复原页面。赛程默认按日期、时间排列，可改为按联赛查看。回放退出时保存进度，可从最近观看继续。":"原生 ExoPlayer HLS / FLV 播放，最低 API 21。设备解码与上游状态仍会影响播放。\n\n不要求账号、不索要存储权限，不绕过登录、付费或 DRM。没有统计 SDK。来源自带的画面广告不受本应用控制。");});}
    void focusFirstCard(){android.graphics.Rect area=new android.graphics.Rect();for(View card:navigationCards)if(card.getGlobalVisibleRect(area)&&area.height()>dp(40)){card.requestFocus();return;}if(!navigationCards.isEmpty())navigationCards.get(0).requestFocus();}
    void contextActions(){View focus=getCurrentFocus();String tag=focus!=null&&focus.getTag() instanceof String?(String)focus.getTag():"";if(tag.startsWith("provider:")&&!tag.equals("provider:全部来源")){connectionDetails(tag.substring(9));return;}Events.Group g=visibleGroups.get(tag);if(g!=null){Ui.options(this,g.lead().label(),new String[]{"观看赛事",Library.favorite(this,g)?"取消收藏":"收藏赛事"},i->{if(i==0)open(g);else try{boolean saved=Library.toggle(this,g);showHint(saved?"已收藏赛事":"已取消收藏");render();}catch(Exception error){Ui.message(this,"收藏失败",error.getMessage());}});return;}Ui.options(this,"快捷操作",new String[]{"来源管理","搜索赛事","刷新赛事","性能与封面"},i->{if(i==0)sourceManager();else if(i==1)search();else if(i==2)refreshNow();else performance();});}
    @Override public boolean dispatchKeyEvent(KeyEvent event){if(event.getAction()==KeyEvent.ACTION_DOWN){lastInput=SystemClock.elapsedRealtime();timer.removeCallbacks(thumbnailScroll);timer.postDelayed(thumbnailScroll,700);int key=event.getKeyCode();View focus=getCurrentFocus();String tag=focus!=null&&focus.getTag() instanceof String?(String)focus.getTag():"";int index=navigationCards.indexOf(focus);if(index>=0&&(key==19||key==20||key==21||key==22)){int target=TvNavigation.target(index,key,navigationColumns,navigationCards.size());if(target>=0&&target<navigationCards.size())navigationCards.get(target).requestFocus();else if(target==navigationCards.size()){if(next.getVisibility()==View.VISIBLE&&next.isEnabled())next.requestFocus();}else if(key==KeyEvent.KEYCODE_DPAD_LEFT)menus.get(view).requestFocus();else{Button chip=providers.get(source);if(chip!=null)chip.requestFocus();}return true;}if(tag.startsWith("nav:")&&key==KeyEvent.KEYCODE_DPAD_RIGHT){focusFirstCard();if(navigationCards.isEmpty())sportsButtons.get(category).requestFocus();return true;}if(tag.startsWith("provider:")&&key==KeyEvent.KEYCODE_DPAD_DOWN){focusFirstCard();return !navigationCards.isEmpty();}if(tag.startsWith("provider:")&&key==KeyEvent.KEYCODE_DPAD_UP){sportsButtons.get(category).requestFocus();return true;}if(tag.startsWith("sport:")&&key==KeyEvent.KEYCODE_DPAD_DOWN){providers.get(source).requestFocus();return true;}if("action:more".equals(tag)&&key==KeyEvent.KEYCODE_DPAD_UP&&!navigationCards.isEmpty()){navigationCards.get(navigationCards.size()-1).requestFocus();return true;}}return super.dispatchKeyEvent(event);}
    public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_MENU){if(event.getRepeatCount()==0)contextActions();return true;}return super.onKeyDown(key,event);}
    protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("view",view);state.putString("source",source);state.putString("category",category);state.putString("query",query);state.putString("league",league);state.putString("date",date);state.putString("scheduleMode",scheduleMode);state.putBoolean("scheduleAll",scheduleAll);SearchSession.Snapshot before=searchSession.origin();if(before!=null){state.putString("searchSource",before.source);state.putString("searchCategory",before.category);state.putString("searchLeague",before.league);state.putString("searchDate",before.date);state.putString("searchFocus",before.focus);state.putInt("searchScroll",before.scroll);}}
    public void onWindowFocusChanged(boolean hasFocus){super.onWindowFocusChanged(hasFocus);windowActive=hasFocus;if(hasFocus){getWindow().getDecorView().setSystemUiVisibility(5894);if(foreground){renderSoon();timer.postDelayed(thumbnailScroll,750);}}}
    protected void onResume(){super.onResume();if(Ui.LIGHT!=Ui.wantsLight(this)){recreate();return;}foreground=true;if(thumbnails!=null)thumbnails.onReturn();render();nav.post(()->{if(getCurrentFocus()==null)menus.get(view).requestFocus();});timer.removeCallbacks(refresh);timer.postDelayed(refresh,15000);if(view.equals("favorites")||view.equals("history"))reload();}
    protected void onPause(){foreground=false;if(liveChecks!=null)liveChecks.pause();timer.removeCallbacks(refresh);super.onPause();}
    protected void onDestroy(){dead=true;if(liveChecks!=null)liveChecks.close();if(thumbnails!=null)thumbnails.close();generation++;timer.removeCallbacksAndMessages(null);requests.shutdownNow();super.onDestroy();}
